TLM.f("Tempora/Pent23-0",{"officium":"Dominica XXIII Post Pentecosten","rule":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Jer 29:11; 29:12; 29:14"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."}],"Oratio":[{"k":"text","la":"Absólve, quǽsumus, Dómine, tuórum delícta populórum: ut a peccatórum néxibus, quæ pro nostra fragilitáte contráximus, tua benignitáte liberémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Phil 3:17-21; 4:1-3"},{"k":"text","la":"Fratres: Imitatóres mei estóte, et observáte eos, qui ita ámbulant, sicut habétis formam nostram. Multi enim ámbulant, quos sæpe dicébam vobis - nunc autem et flens dico - inimícos Crucis Christi: quorum finis intéritus: quorum Deus venter est: et glória in confusióne ipsórum, qui terréna sápiunt. Nostra autem conversátio in cœlis est: unde étiam Salvatórem exspectámus, Dóminum nostrum Jesum Christum, qui reformábit corpus humilitátis nostræ, configurátum córpori claritátis suæ, secúndum operatiónem, qua étiam possit subjícere sibi ómnia. Itaque, fratres mei caríssimi et desideratíssimi, gáudium meum et coróna mea: sic state in Dómino, caríssimi. Evódiam rogo et Sýntychen déprecor idípsum sápere in Dómino. Etiam rogo et te, germáne compar, ádjuva illas, quæ mecum laboravérunt in Evangélio cum Cleménte et céteris adjutóribus meis, quorum nómina sunt in libro vitæ."}],"Graduale":[{"k":"ref","la":"Ps 43:8-9"},{"k":"text","la":"Liberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti."},{"k":"text","la":"In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 9:18-26"},{"k":"text","la":"In illo témpore: Loquénte Jesu ad turbas, ecce, princeps unus accéssit et adorábat eum, dicens: Dómine, fília mea modo defúncta est: sed veni, impóne manum tuam super eam, et vivet. Et surgens Jesus sequebátur eum et discípuli ejus. Et ecce múlier, quæ sánguinis fluxum patiebátur duódecim annis, accéssit retro et tétigit fímbriam vestiménti ejus. Dicébat enim intra se: Si tetígero tantum vestiméntum ejus, salva ero. At Jesus convérsus et videns eam, dixit: Confíde, fília, fides tua te salvam fecit. Et salva facta est múlier ex illa hora. Et cum venísset Jesus in domum príncipis, et vidísset tibícines et turbam tumultuántem, dicebat: Recédite: non est enim mórtua puélla, sed dormit. Et deridébant eum. Et cum ejécta esset turba, intrávit et ténuit manum ejus. Et surréxit puélla. Et éxiit fama hæc in univérsam terram illam."}],"Offertorium":[{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine."}],"Secreta":[{"k":"text","la":"Pro nostræ servitútis augménto sacrifícium tibi, Dómine, laudis offérimus: ut, quod imméritis contulísti, propítius exsequáris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 11:24"},{"k":"text","la":"Amen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, quos divína tríbuis participatióne gaudére, humánis non sinas subjacére perículis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"bd185627d98770c9":{"t":"<i>Pomolimo se</i>.\nOprosti, molimo, Gospodine, zla djela svojim ljudima, da se od veza grijeha, u koje smo upali po svojoj slabosti, oslobodimo tvojom blagošću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Odriješi, molimo. Gospodine, prekršaje Tvojih naroda, da se od spona grijeha, kojih se svojom slabošću dobavismo!, Tvojom blagošću oslobodimo, PO G. n.","knRef":"Kniewald 1942, str. 430–431 (snimka 216) (OCR)"},"79c66798866e4ba3":{"t":"Prinosimo ti, Gospodine, žrtvu hvale za uspjeh naše službe, da ti milostivo dovršiš ono što si povjerio nama nevrijednima da činimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prinosimo Ti. Gospodine, žrtvu hvale, da poraste revnost naše službe, te milostivo savršiš ono, što si nevrijednima udijelio, po G. n.","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"cd09b0a2c526ca43":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, ne dopusti da nas svladaju zemaljske pogibli, kad si nam dao radost da budemo dionici božanskih ostajstava.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, svemogući Bože, ne dopusti, da podlegnemo pogiblima i napastirria, kad dopuštaš, da se po Tvojoj darežljivosti radujemo u božanskom prićešćenju, po G. n.","knRef":"Kniewald 1942, str. 432–433 (snimka 217) (OCR)"},"ba591f95b6d2e86d":{"t":"Jer 29, 11-12.14, Ps 84, 2\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva. (Ps 84, 2) Blagoslovio si, Gospodine, svoju zemlju, na dobro si okrenuo Jakovljevu sudbinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva.","kn":"perem. 29. 11-14). Govori Gospodin: Ja mislim misli mira, a ne cviljenja; prizivat ćete me i ja ću vas uslišati, i izvest ću robovanje vaše iz svih mjesta. (Ps. 84. 2) Blagoslovio si, Gospodine, zemlju svoju, povratio si roblje Jakovljevo. Slava Oću . . . Govori Gospodin .• •","knRef":"Kniewald 1942, str. 432–433 (snimka 217) (OCR)"},"3f58783f5d8249b9":{"t":"Fil 3, 17-21; 4, 1-3\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo: Ugledajte se u mene i vladajte se prema onima koji žive po primjeru koji vam mi dajemo. Mnogi, o kojima sam vam često govorio, a sada plačući ponavljam, žive kao neprijatelji Kristova križa. Njihov će svršetak biti propast, jer im je bog trbuh i ponose se svojom sramotom. Oni teže samo za zemaljskim stvarima. Naša je, međutim, domovina na nebu, odakle i očekujemo Spasitelja, Gospodina Isusa Krista, koji će silom, kojom može sve podložiti sebi, preobraziti naše bijedno tijelo i učiniti ga jednakim svome slavnom tijelu. –: Zato, moja draga i željena braćo, radosti moja i kruno moja, ustrajte, predragi, u Gospodinu! Žarko molim Evodiju i Sintihu, da isto misle u Gospodinu. A molim i tebe, vjerni druže, da im pomogneš, jer su mi one pomogale u širenju Evanđelja zajedno s Klementom i s drugim mojim suradnicima, kojih su imena upisana u knjizi života.","kn":"Čitanje poslanice bi. Pavla apostola Filipljanima (3, 17-21, 4, 1-3). Braćo! Ugledajte se na me i promatrajte one, koji žive po primjeru, koji imate u nama. Jer mnogi, o kojima sam vam često govorio, a sada vam i sa suzama kažem, žive 'kao neprijatelji Kristova križa. Njihov svršetak je propast, njihov bog je trbuh, a slava u njihovoj sramoti, jer teže samo za zemaljskim stvarima. A naša je domovina na nebu, odakle očekujemo Spasitelja, Gospodina našega Isusa Krista. On će po jakosti, koja može sebi pokoriti sve, preobraziti naše bijedno tijelo, da bude jednako njegovu proslavljenom tijelu. Zato, moja' predraga i željkovana braćo mojaradosU i moj vijenče, tako ustrajte, predragi u Gospodinu! Evodiju molim i Sintihu prosim, ’da isto misle u Gospodinu. A i tebe, vjerni druže.i molim, pomozi onima, koji su se trumii u evanđedjii s Klementora i mojim drugim pom^- nicima, kojih su imena u knjizi života,","knRef":"Kniewald 1942, str. 430–431 (snimka 216) (OCR)"},"a8b02c4b81c26ed7":{"t":"Ps 43, 8-9\nSpasio si nas, Gospodine, od naših protivnika i smeo si naše mrzitelje. U Bogu je naša slava u svako doba, i uvijek hvalimo ime tvoje.\n\nPs 129, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. <i>Aleluja</i>.","kn":"(Ps. 43, 8, 9). Oslobodio si nas, Gospodine, od onih, koji nas mučiše i smeo si one, koji mrziše na nas. U Bogu ćemo se hvaliti cijeli dan. 1 slavit ćemo ime Tvoje u vijeke.\n\nAleluja, aleluja. (Ps. 129, 1, 2) Iz dubine vapijem k Tebi, Gospodine; Gospodine usliši molitvu moju, aleluja. r, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"433537861ad11bf0":{"t":"Mt 9, 18-26\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Dok je Isus govorio narodu, pristupi neki poglavar, padne pred njega ničice i reče: »Gospodine, kći je moja malo prije umrla. Dođi, položi svoju ruku na nju, i ona će oživjeti.« Isus ustade i pođe za njim, a s Isusom pođu i njegovi učenici. – Ali, gle. neka žena koja je dvanaest godina bolovala od krvarenja približi se straga i dotakne se njegove haljine. Ona je vjerovala u sebi: Ako se samo' dataknem njegove haljine, ozdravit ću! Isus se okrene, pogleda je te joj reče: »Uzdaj se, kćeri, vjera te je tvoja ozdravila!« I žena ozdravi toga časa. – Kad je Isus stigao u kuću poglavara, vidi svirače i uzbuđeni narod pa reče: »Odmaknite se, jer djevojka nije umrla, nego spava.« A ljudi se rugahu njegovoj tvrdnji. Ali Isus udalji narod, uđe u sobu, primi za ruku djevojku i ona ustade. I glas se o tome raširi po svom onom kraju.","kn":"t Slijedi sveto evanđelje Po Mateju (9, 18-M). U ono vrijeme, dok je Isus govorio narodu, pristupi mu neki knez, pokloni mu se i reče: Gospodine, moja kći je sada preminula; dođi, metni na nju svoju ruku i oživjet će. Isus ustade i pođe za njim sa svojim učenicima. I žena, koja . je dvanaest godina bolovala od gubitka krvi, pristupi otraga i dotaće se okraoka njeego.ve haljine. Jer je pomislila u sebi: Ozdravit ću, samo ako se dotaknem njegove haljine. A Isus se okrenu, ugleda jo i reče. Uzdaj se, kćeri, ozdravila te je tvoje vjera! I žena ^ ozdi-avi onoga časa. Kad je Isus došao do kneževe kuće i vidio svirače i narod, koji je bucio, reče Otstupite, jer djevojka nije Umrla, nego spava. I filnijali su mu se. I kad je istjerao narod, uđe u kuću, uze ruku djevojke 1 djevojka je ustala..! taj glas proču se po svemu onom^kraju Vjerujem. ^ ' ' V'o--.. ; ■","knRef":"Kniewald 1942, str. 430–431 (snimka 216) (OCR)"},"8a9f1217916db598":{"t":"Ps 129, 1-2\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. Iz dubine vapijem k tebi, Gospodine.","kn":"(Ps. 129, 1-2). Iz dubine vapijem k Tebi, Gospodine; Gospodine, usliši molitvu moju; iz dubine vapijem k Tebi, Gospodine.","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Go. spodine sveti, Oće svemogući, vječni Bože, koji si sa Sinom svojim i s Duhom Svetim jedan Bog i je- dan Gospodin: ne u jedinstvu osobe, nego u Trojstvu jedne biti. Jer sve, što po Tvojem otkrivenju vjerujemo o Tvojoj slavi, to bez razlike i razlučivanja mislimo i o Sinu Tvoj emu i o Duhu Svetomu. Ispovijedajući pravo i vječno Božanstvo, klanjamo se tako i vlastitosti u osobama i jedinstvu u biti i jednakosti u veličanstvu, koje hvale anđeli i arkanđeli, kerubini i serafini, koji ne prestaju klicati svakog dana jednoglasno govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"2a2aa3c192299041":{"t":"Mk 11, 24\nZaista vam kažem: Što god moleći zaištete, vjerujte da ćete dobiti, i bit će vam.","kn":"(Mk., 11, 24). Zaista vam kažem, štogod moleći zaištete, vjerujte, da ćete primiti, i bit će vam.","knRef":"Kniewald 1942, str. 432–433 (snimka 217) (OCR)"}}});
